# ==============================================================================# IOTEC MISSION CONTROL# 007_SERVICE_REGISTRY.py# ==============================================================================import jsonfrom pathlib import Pathfrom datetime import datetimeROOT = Path(__file__).resolve().parentCONFIG = ROOT / "MISSION_CONTROL" / "config"CONFIG.mkdir(parents=True, exist_ok=True)REGISTRY = CONFIG / "service_registry.json"SERVICES = [    {        "id": 1,        "name": "BOOT",        "module": "001_BOOT.py",        "status": "ONLINE",        "critical": True    },    {        "id": 2,        "name": "KERNEL",        "module": "002_KERNEL.py",        "status": "ONLINE",        "critical": True    },    {        "id": 3,        "name": "EVENT_BUS",        "module": "003_EVENT_BUS.py",        "status": "ONLINE",        "critical": True    },    {        "id": 4,        "name": "DATABASE",        "module": "004_DATABASE.py",        "status": "ONLINE",        "critical": True    },    {        "id": 5,        "name": "LOG_ENGINE",        "module": "005_LOG_ENGINE.py",        "status": "ONLINE",        "critical": False    },    {        "id": 6,        "name": "CONFIG_ENGINE",        "module": "006_CONFIGURATION_ENGINE.py",        "status": "ONLINE",        "critical": False    }]registry = {    "generated_at": datetime.now().isoformat(),    "total_services": len(SERVICES),    "services": SERVICES}with open(REGISTRY, "w", encoding="utf-8") as f:    json.dump(registry, f, indent=4, ensure_ascii=False)print("=" * 80)print("SERVICE REGISTRY")print("=" * 80)print(f"ServiÃ§os: {len(SERVICES)}")for s in SERVICES:    print(f"[{s['status']}] {s['name']}")print("=" * 80)

